const revealNodes = document.querySelectorAll(".reveal");
const navLinks = document.querySelectorAll(".site-nav a");
const sections = document.querySelectorAll("section[id]");
const langToggle = document.getElementById("langToggle");
const themeToggle = document.getElementById("themeToggle");
const ambientA = document.querySelector(".ambient-a");
const ambientB = document.querySelector(".ambient-b");
const scrollProgress = document.querySelector(".scroll-progress");

let currentLang = localStorage.getItem("lang") || "vi";
let currentTheme = localStorage.getItem("theme") || "light";
let ticking = false;

const prefersReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

const runTransition = (update) => {
  if (prefersReduced || !document.startViewTransition) return update();
  document.startViewTransition(update);
};

const applyLanguage = (lang, persist = true) => {
  const bundle = translations[lang] || translations.vi;
  document.documentElement.lang = lang;
  document.querySelectorAll("[data-i18n]").forEach((node) => {
    const key = node.dataset.i18n;
    const text = bundle[key];
    if (!text) return;
    if (node.dataset.i18nType === "html") node.innerHTML = text;
    else node.textContent = text;
  });
  currentLang = lang;
  langToggle.textContent = lang.toUpperCase();
  langToggle.title = lang === "vi" ? "Switch to English" : "Chuyển sang tiếng Việt";
  if (persist) localStorage.setItem("lang", lang);
};

const applyTheme = (theme, persist = true) => {
  document.body.classList.toggle("theme-dark", theme === "dark");
  themeToggle.textContent = theme === "dark" ? "☀" : "🌙";
  themeToggle.title = theme === "dark" ? "Chuyển giao diện sáng" : "Chuyển giao diện tối";
  currentTheme = theme;
  if (persist) localStorage.setItem("theme", theme);
};

const setActiveNav = (id) => {
  navLinks.forEach((link) => {
    const target = link.getAttribute("href");
    link.classList.toggle("is-active", target === `#${id}`);
  });
};

const revealObserver = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("show");
      revealObserver.unobserve(entry.target);
    });
  },
  { threshold: 0.14, rootMargin: "0px 0px -10% 0px" }
);

revealNodes.forEach((node, index) => {
  node.style.setProperty("--delay", `${index * 54}ms`);
  revealObserver.observe(node);
});

const sectionObserver = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      setActiveNav(entry.target.id);
    });
  },
  { threshold: 0.55 }
);

sections.forEach((section) => sectionObserver.observe(section));

const updateScrollEffects = () => {
  const max = document.documentElement.scrollHeight - window.innerHeight;
  const progress = max > 0 ? window.scrollY / max : 0;
  if (scrollProgress) scrollProgress.style.setProperty("--progress", progress.toFixed(4));
  ticking = false;
};

const onScroll = () => {
  if (ticking) return;
  ticking = true;
  requestAnimationFrame(updateScrollEffects);
};

const moveAmbient = (event) => {
  const x = (event.clientX / window.innerWidth - 0.5) * 20;
  const y = (event.clientY / window.innerHeight - 0.5) * 20;
  if (ambientA) ambientA.style.transform = `translate(${-x}px, ${-y}px)`;
  if (ambientB) ambientB.style.transform = `translate(${x}px, ${y}px)`;
};

window.addEventListener("scroll", onScroll, { passive: true });
window.addEventListener("resize", onScroll);
window.addEventListener("pointermove", moveAmbient, { passive: true });

document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
  anchor.addEventListener("click", (event) => {
    const id = anchor.getAttribute("href");
    const target = id && id !== "#" ? document.querySelector(id) : null;
    if (!target) return;
    event.preventDefault();
    target.scrollIntoView({ behavior: prefersReduced ? "auto" : "smooth", block: "start" });
  });
});

langToggle.addEventListener("click", () => {
  const nextLang = currentLang === "vi" ? "en" : "vi";
  runTransition(() => applyLanguage(nextLang));
});

themeToggle.addEventListener("click", () => {
  const nextTheme = currentTheme === "light" ? "dark" : "light";
  runTransition(() => applyTheme(nextTheme));
});

applyLanguage(currentLang, false);
applyTheme(currentTheme, false);
setActiveNav("gioi-thieu");
onScroll();
